css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 7px 12px 9px; margin-bottom: 11px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 4px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12.5px; margin-bottom: 4px; line-height: 1.35;}
.mz .recuerda-ejemplos{display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 7px;}
.mz .rec-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 4px 5px; display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .rec-caja svg{width: 84px; height: 84px;}
.mz .rec-label{font-size: 12.5px; font-weight: 700;}
.mz .sino-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 9px;}
.mz .sino-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 4px 5px; display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .sino-caja svg{width: 82px; height: 82px;}
.mz .sino-ops{font-family: sans-serif; font-weight: 700; font-size: 13px; white-space: nowrap;}
.mz .eje-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px;}
.mz .eje-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 4px 5px; display: flex; flex-direction: column; align-items: center; gap: 4px;}
.mz .eje-caja svg{width: 88px; height: 88px;}
.mz .eje-ops{font-family: sans-serif; font-weight: 700; font-size: 13.5px; white-space: nowrap;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 9px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; border-bottom: 1px dotted #999; padding-bottom: 5px;}
.mz .vf-opciones{font-family: sans-serif; font-weight: 700; font-size: 12.5px; white-space: nowrap;}
.mz .recuerda-idea{line-height: 1.725 !important;}
